```javascript
// Constantes globales (definidas fuera del scope de la función)
const NUM_ROWS = 20;
const NUM_COLUMNS = 10;
const COLUMN_LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

// Función para obtener el valor de una celda o calcularlo si es necesario.
function getCellValue(cellElement) {
    if (!cellElement || !cellElement.dataset.row || !cellElement.dataset.col) return null;
    let value = cellElement.innerText.trim();

    // Si la celda tiene una fórmula, debe evaluarse antes de devolver el valor
    if (value.startsWith('=')) {
        try {
            return calculateFormula(cellElement, value);
        } catch (e) {
            console.error("Error calculating formula:", e);
            return value; // Devolver la fórmula si falla el cálculo
        }
    }

    // Limpiar cualquier contenido extra de tipo P o SPAN que pueda venir del innerText
    if (value === '') return '';
    return value;
}

// Función para calcular fórmulas estilo Excel.
function calculateFormula(cellElement, formula) {
    let expression = formula;
    const sheetData = getSheetData();

    // 1. Reemplazar nombres de celdas (A1, B2:C3, etc.) con valores numéricos o referencias funcionales
    expression = expression.replace(/([A-Z]+)([0-9]+)/g, (match) => {
        const colLetter = match[1];
        const rowNum = parseInt(match[2]);

        // Obtener el valor de la referencia actual en el DOM para el cálculo
        const cellElementRef = document.querySelector(`.cell[data-col="${colLetter}"][data-row="${rowNum}"]`);
        if (cellElementRef) {
            let value = getCellValue(cellElementRef);
            // Si es un rango, necesitamos tratarlo como una función de suma o simplemente el valor si no hay funciones.
            return isNaN(parseFloat(value)) ? '0' : value; 
        }
        return '0'; // Valor por defecto si la celda no existe (debería ser manejado antes)
    });

    // Manejo de rangos: A1:A3 -> SUMA(valor_A1, valor_A2, valor_A3) o simplemente concatenar valores.
    expression = expression.replace(/([A-Z]+[0-9]+):([A-Z]+[0-9]+)/g, (match, startCell, endCell) => {
        // Esta implementación simplificada solo manejará la suma de rangos si es necesario. 
        // Para el scope del problema y los ejemplos dados (=SUMA(A1:A3)), asumiremos que SUMA ya maneja esto o que necesitamos un valor único.
        return `(${match})`; // Dejarlo como un grupo para que Math evalúe la suma si es necesario, aunque idealmente debería ser manejado por lógica de rangos.
    });


    // 2. Evaluar la expresión matemática resultante (ej: "9 + 10")
    try {
        // Usamos Function constructor para ejecutar el cálculo en un ámbito controlado
        const result = new Function('return ' + expression)();
        if (!isNaN(result)) {
            return result;
        } else {
            return formula; // Si falla la conversión a número, devolver la fórmula original
        }
    } catch (e) {
        console.error("Error evaluating mathematical expression:", e);
        return formula;
    }
}

// Recopila todos los valores visibles de las celdas para un cálculo global
function getSheetData() {
    const cells = document.querySelectorAll('.cell');
    let data = {};
    cells.forEach(cell => {
        data[`${cell.dataset.col}${cell.dataset.row}`] = getCellValue(cell);
    });
    return data;
}


// Inicializa el grid de la hoja de cálculo, creando filas y celdas dinámicamente.
function initializeSpreadsheetGrid() {
    const spreadsheetContainer = document.getElementById('spreadsheet');
    if (!spreadsheetContainer) return;

    // Dado que el HTML ahora incluye la fila 1, solo generamos las filas restantes (2 a 20).

    // Contar cuántos elementos de clase 'row-label' ya existen para determinar dónde empezar.
    const existingRowLabels = spreadsheetContainer.querySelectorAll('.row-label');
    let startRowIndex = 1;
    if (existingRowLabels.length > 0) {
        // Asumimos que el primer row-label encontrado es la fila 1, y empezamos a generar desde la siguiente.
        startRowIndex = parseInt(existingRowLabels[0].dataset.row) + 1;
    }

    for (let r = startRowIndex; r <= NUM_ROWS; r++) {
        let rowHtml = '';

        // 1. Generar etiqueta de fila (el número)
        rowHtml += `<div class="row-label" data-row="${r}">${r}</div>`;

        // 2. Generar las celdas para la fila actual
        for (let c = 0; c < NUM_COLUMNS; c++) {
            const colLetter = COLUMN_LETTERS[c];
            // Nota: Se mantiene contenteditable="true" y se le añade el listener en la inicialización.
            rowHtml += `<div class="cell editable" contenteditable="true" data-col="${colLetter}" data-row="${r}" tabindex="0"></div>`;
        }

        spreadsheetContainer.innerHTML += rowHtml;
    }
}


// Configura los listeners de eventos para las celdas recién añadidas y existentes.
function setupCellInteractivity() {
    const cells = document.querySelectorAll('.cell');

    cells.forEach(cell => {
        // Limpiamos listeners previos antes de reasignar si la función se llama varias veces
        cell.onblur = null; 
        cell.oninput = null;

        // Listener para cuando el usuario termina de editar (pierde el foco)
        cell.addEventListener('blur', function() {
            handleCellChange(this);
        });

        // Listener para la entrada de texto en tiempo real
        cell.addEventListener('input', function() {
            if (this.innerText.trim().startsWith('=')) {
                calculateAndDisplayResult(this);
            } else if (!isNaN(parseFloat(this.innerText))) {
                 handleCellChange(this); // Si es solo un número, actualizamos inmediatamente
            }
        });
    });

    // Listener global para detectar cambios en cualquier parte del grid (ej: al hacer clic y escribir)
    document.getElementById('spreadsheet').addEventListener('input', function(e) {
        const target = e.target;
        if (target.classList.contains('cell') && target.contentEditable === 'true') {
            calculateAndDisplayResult(target);
        }
    });
}

// Maneja el cambio de valor en una celda: actualiza valores y recalcula dependencias.
function handleCellChange(changedCell) {
    const col = changedCell.dataset.col;
    const row = changedCell.dataset.row;
    let value = getCellValue(changedCell);

    // 1. Actualizar el valor visible de la celda si es un cálculo
    if (value !== null && typeof value === 'number') {
        changedCell.innerText = value;
    } else if (typeof value === 'string' && !isNaN(parseFloat(value))) {
         changedCell.innerText = value;
    }

    // 2. Recalcular todas las celdas que dependan de esta celda.
    recalculateDependentCells(col, row);
}


// Intenta encontrar y recalcular todas las celdas cuyo valor depende de la celda (col, row).
function recalculateDependentCells(changedCol, changedRow) {
    const allCells = document.querySelectorAll('.cell');
    let recalculatedCount = 0;

    allCells.forEach(cell => {
        // Solo nos interesa recalcular celdas que contienen fórmulas
        if (cell.innerText && cell.innerText.trim().startsWith('=')) {
            const col = cell.dataset.col;
            const row = cell.dataset.row;

            // Lógica de dependencia simple: Si la celda A1 cambió, recalcular B2 si B2 usa A1.
            // Para una implementación robusta, se necesitaría un grafo de dependencias. 
