function calculateFormula(cell) {
    const content = cell.textContent.trim();

    if (!content || typeof content !== 'string') return;

    // 1. Check if it is a formula (starts with '=')
    if (content.startsWith('=')) {
        let formulaString = content.substring(1).toUpperCase().trim();

        try {
            // Simple parsing logic for required functions/operations
            if (formulaString.startsWith("SUMA")) {
                // Expect format: SUMA(A1:A3) or SUMA(A1;B2;C3)
                let args = formulaString.substring(4).trim();
                const cellReferences = extractCellReferences(args);

                if (cellReferences.length === 0) {
                    return "Error: Rango inválido";
                }

                // For simplicity in this scope, we treat all references as individual cells
                let sumResult = 0;
                for (const ref of cellReferences) {
                    sumResult += getCellValue(ref);
                }
                return sumResult.toString();

            } else if (formulaString.includes('-')) {
                // Basic subtraction: A1-B1 (assuming single references for now)
                let parts = formulaString.split('-');
                if (parts.length >= 2) {
                    let result = getCellValue(extractCellReference(parts[0]));
                    for (let i = 1; i < parts.length; i++) {
                        result -= getCellValue(extractCellReference(parts[i]));
                    }
                    return result.toString();
                }

            } else if (formulaString.includes('*')) {
                // Basic multiplication: A1*B1
                 let parts = formulaString.split('*');
                if (parts.length >= 2) {
                    let result = getCellValue(extractCellReference(parts[0]));
                    for (let i = 1; i < parts.length; i++) {
                        result *= getCellValue(extractCellReference(parts[i]));
                    }
                    return result.toString();
                }

            } else if (formulaString.includes('/')) {
                 // Basic division: A1/B1
                let parts = formulaString.split('/');
                if (parts.length >= 2) {
                    let result = getCellValue(extractCellReference(parts[0]));
                    for (let i = 1; i < parts.length; i++) {
                        result /= getCellValue(extractCellReference(parts[i]));
                    }
                    return result.toString();
                }

            } else {
                // If it starts with '=' but doesn't match known syntax, treat as error or text? For now, just return the formula if unknown.
                return content; 
            }
        } catch (e) {
            console.error("Error calculating formula:", e);
            return "Error";
        }
    }

    // If it's not a formula, return the current value
    return content;
}


/** Helper function to get numeric value from a referenced cell element. */
function getCellValue(reference) {
    const [colLetter, rowNum] = reference.match(/([A-Z]+)(\d+)/i);
    if (!colLetter || !rowNum) return 0;

    // Find the actual DOM element corresponding to the reference
    const targetCell = document.querySelector(`.cell[data-col="${colLetter}"][data-row="${rowNum}"]`);

    if (targetCell && targetCell.textContent.trim().startsWith('=')) {
        // If the target cell contains a formula, we must calculate it first to get its displayed result
        return parseFloat(calculateFormula(targetCell));
    } else if (targetCell) {
        const text = targetCell.textContent.trim();
         if (!isNaN(parseFloat(text))) {
            return parseFloat(text);
        }
    }
    return 0; // Default value if cell is empty or invalid
}

/** Helper to extract all valid references separated by commas or semicolons, assuming SUMA use case (range/multiple cells). */
function extractCellReferences(args) {
    // Matches patterns like A1:A3 or A1, B2;C3. We treat ranges for simplicity here as a list of single cell references.
    const matches = [...args.matchAll(/([A-Z]+[0-9]+(?::[A-Z]+[0-9]+)?))/gi)];
    let refs = [];
    for (const match of matches) {
        const fullRef = match[0].toUpperCase();

        // If it's a range (e.g., A1:A3), we need to extract all individual cells in the range.
        if (fullRef.includes(':')) {
            const [start, end] = fullRef.split(':');
            let startCol = start[0];
            let startRow = parseInt(start.substring(1));
            let endCol = end[0];
            let endRow = parseInt(end.substring(1));

            // Simple assumption: only calculate if column letters match (vertical range)
            if (startCol === endCol) {
                 for (let r = startRow; r <= endRow; r++) {
                    refs.push(`${startCol}${r}`);
                }
            } else {
                // Handle horizontal ranges or complex ranges if necessary, but for this fix, stick to basic vertical/single cell logic.
                refs.push(fullRef); 
            }

        } else {
            refs.push(fullRef);
        }
    }
    return refs;
}

/** Helper to extract a single reference (e.g., A1) */
function extractCellReference(part) {
    // This assumes the input part is already clean and just needs formatting/cleaning
    let cleaned = part.trim().toUpperCase();
    if (!cleaned) return null;
    return cleaned;
}
