            safeExpression = safeExpression.replace(/([A-Z]+)([0-9]+)/g, (match, colLetter, rowNumberStr) => {
                const colIndex = COLUMN_LETTERS.indexOf(colLetter);
                const rowIndex = parseInt(rowNumberStr);
                if (colIndex === -1 || isNaN(rowIndex)) return match; // No es una referencia válida

                // Obtener el valor de la celda referenciada en el DOM
                const targetCell = document.querySelector(`.cell[data-col="${colLetter}"][data-row="${rowIndex}"]`);
                if (targetCell) {
                    let content = targetCell.textContent.trim();
                     // Si el contenido es una fórmula, evaluamos ese valor. Si no, lo usamos directamente.
                    if (content && content.startsWith('=')) {
                        const calculatedValue = calculateFormula(targetCell);
                        return calculatedValue !== null ? calculatedValue : targetCell.textContent;
                    }
                    // Intentar convertir a número si es un contenido simple
                    return parseFloat(content) || 0;
                }
                return match; // Devolver el texto original si no se encuentra la celda
            });

            // Usamos Function constructor para evaluar la expresión matemática de forma segura.
            const result = new Function('return ' + safeExpression);
            let resultValue = result();

             if (isNaN(resultValue) || !isFinite(resultValue)) {
                 return "Error";
             }
            return parseFloat(resultValue).toFixed(2);
        }
    } catch (e) {
        console.error("Error al calcular la fórmula:", e);
        return "ERROR";
    }
}

function evaluateFunctionFormula(formulaBody, currentCell) {
    // Esta es una implementación muy simplificada para SUMA y requiere que el motor de JS maneje las referencias.
    if (formulaBody.toUpperCase().startsWith("SUMA")) {
        const match = formulaBody.match(/SUMA\((.*)\)/i);
        if (!match || !match[1]) return "ERROR";

        const argumentsList = match[1].split(';'); // Separador de argumentos en español es ';'
        let sum = 0;
        argumentsList.forEach(arg => {
            // Asumimos que cada argumento es una celda o rango simple (ej: A1, B2:C3)
