              if (singleCellMatch) {
                 const colLetter = singleCellMatch[1];
                 const rowNumberStr = singleCellMatch[2];

                 const targetCell = document.querySelector(`.cell[data-col="${colLetter}"][data-row="${rowNumberStr}"]`);
                  if (targetCell) {
                      let content = targetCell.textContent.trim();
                       // Si la celda referenciada contiene una fórmula, calculamos su valor real primero.
                      if (content && content.startsWith('=')) {
                           const calculatedValue = calculateFormula(targetCell);
                           sum += parseFloat(calculatedValue) || 0;
                      } else {
                            sum += parseFloat(content) || 0;
                      }
                 }
             }
        });

        return sum.toFixed(2);
    }
    // Añadir lógica para otras funciones (PROMEDIO, etc.) aquí...
    return "ERROR"; // Función no soportada o formato incorrecto
