/**
 * Intenta evaluar una fórmula simple de hoja de cálculo basada en los valores actuales del grid.
 * Asume que las fórmulas son operaciones aritméticas simples (e.g., "=A1+B2").
 * @param {string} formula El contenido de la celda que debe comenzar con '='.
 * @returns {string | null} El resultado calculado como string, o null si falla.
 */
function calculateCellValue(formula) {
    if (!formula || !formula.startsWith('=')) return null;

    let expression = formula.substring(1).trim(); // Elimina '=' y trimmea espacios iniciales/finales
    const cellRegex = /([A-Z]+[0-9]+)/g; 

    // Reemplaza las referencias de celda (ej: B1) por sus valores reales en el DOM.
    expression = expression.replace(cellRegex, (match) => {
        const [colLetter, rowNumber] = match.toUpperCase().match(/([A-Z]+)([0-9]+)/);
        if (!colLetter || !rowNumber) return '0'; // Fallback

        // Buscamos el elemento de la celda en el DOM que corresponde a la referencia (e.g., A1)
        const targetCell = document.querySelector(`.cell[data-col="${colLetter}"][data-row="${rowNumber}"]`);

        let value;
        if (targetCell && targetCell.textContent.trim() !== '') {
            // Intentamos obtener el valor numérico visible de la celda dependiente.
             value = parseFloat(targetCell.textContent.trim());
        } else {
            value = 0;
        }

        return isNaN(value) ? '0' : value.toString();
    });

    try {
        // Ejecuta el cálculo usando new Function para evitar la evaluación directa de código peligroso (eval()).
        const result = new Function('return ' + expression)();
        return isNaN(result) ? null : String(Math.round(result * 100) / 100); // Limita a dos decimales si es necesario, o simplemente usa toString()
    } catch (e) {
        console.error("Error al calcular la fórmula:", e);
        return null;
    }
}

/**
