 * actualizando su contenido visible si es necesario.
 */
function recalculateGrid() {
    const editableCells = document.querySelectorAll('.cell.editable');

    editableCells.forEach(cell => {
        let formulaContent = cell.textContent.trim();
        const col = cell.dataset.col;
        const row = cell.dataset.row;

        if (formulaContent && formulaContent.startsWith('=')) {
            // 1. Recalcular el valor basado en las dependencias actuales.
