function calculateCellValue(cellElement) {
    let content = cellElement.textContent.trim();

    // 1. Verificar si es una fórmula
    if (!content || !content.startsWith('=')) {
        return content; // No es fórmula, devolver texto/valor directo
    }

    // Eliminar el '=' inicial para procesar la expresión
    let formula = content.substring(1).trim();

    // 2. Reemplazar referencias de celda (ej: B1) por sus valores actuales
    // Esta regex busca patrones como [A-Z]+[0-9]+ y los reemplaza con su valor real del DOM.
    const references = {
        match: /([A-Z]+\d+)/g,
        replace: (match) => {
            // Obtener el elemento de celda correspondiente en el DOM para obtener su valor actual.
            const cellRef = document.querySelector(`.cell[data-col="${match.slice(0, -1)}"][data-row="${match.slice(-1)}"]`);
            if (cellRef) {
                // Intentar usar el texto visible del elemento de celda como su valor. 
                // Esto es crucial porque si la referencia está en una fórmula calculada, ya debe reflejar un número.
                const value = cellRef.textContent.trim();
                return isNaN(parseFloat(value)) ? (typeof parseFloat(value) === 'number' && !isNaN(parseFloat(value)) ? parseFloat(value) : 0) : value;
            }
            // Si no se encuentra la referencia, asumimos un valor de 0 para evitar fallos.
            return '0';
        }
    };

    let expression = formula.replace(references.match, references.replace);

    try {
        // 3. Evaluar la expresión matemática resultante (ej: "2 + 3")
        // Usamos eval() con precaución, pero es necesario aquí para evaluar expresiones matemáticas dinámicas.
        const result = Function('return ' + expression)();
        return isNaN(result) ? "" : result; // Devolver el resultado numérico formateado
    } catch (e) {
        console.error("Error al calcular la fórmula:", e);
        // En caso de error, devolver el valor original o un mensaje de error.
        return content; 
    }
}
