function handleCellFocus(cell) {
    const container = document.getElementById('color-picker-container');
    if (!container) return;

    // 1. Establecer la visibilidad de los controles
    container.style.display = 'block';

    // 2. Actualizar el color picker con el fondo actual de la celda
    const currentColor = cell.style.backgroundColor || '#ffffff';
    document.getElementById('bg-color-input').value = currentColor;

    // 3. Limpiar listeners anteriores y añadir nuevos para manejar el evento en este foco específico
    const applyColorBtn = document.getElementById('apply-color-btn');

    // Evitar múltiples listeners si la función se llama varias veces sin limpiar
    applyColorBtn.onclick = function() {
        const selectedColor = document.getElementById('bg-color-input').value;
        cell.style.backgroundColor = selectedColor;
        console.log(`Fondo de ${cell.dataset.col}${cell.dataset.row} cambiado a ${selectedColor}`);

        // Opcionalmente, si se requiere que el cambio sea persistente o active otra lógica:
        // saveCellBackground(cell, selectedColor); 
    };
}
