/**
 * Borra el contenido de todas las celdas asociadas a una columna dada.
 * @param {string} colLetter Letra de la columna (A-J).
 */
function clearColumnContents(colLetter) {
    const cells = document.querySelectorAll(`.cell[data-col="${colLetter}"]`);
    cells.forEach(cell => {
        // Limpiar el contenido visible y resetear estilos para que parezca borrado
        cell.textContent = '';
        cell.style.backgroundColor = ''; // Reset color de fondo
    });
}
