### FUNCION: selectColumn
```js
function selectColumn(letter) {
    // 1. Deseleccionar cualquier columna previamente seleccionada y resetear estilos.
    document.querySelectorAll('.col-letter').forEach(el => el.classList.remove('selected'));
    document.querySelectorAll('.cell.editable').forEach(cell => cell.style.backgroundColor = '');

    // 2. Marcar la letra de la columna activa.
    const colLetterElement = document.querySelector(`.col-letter[data-letter="${letter}"]`);
    if (colLetterElement) {
        colLetterElement.classList.add('selected');
        document.getElementById('current-column-display').textContent = `Columna ${letter} seleccionada`;
        // Al seleccionar, podemos también asegurar que la columna se pueda editar/aplicar estilos.
        window.selectedColumnLetter = letter;
    } else {
        console.error(`No se encontró la letra de columna: ${letter}`);
        window.selectedColumnLetter = null;
    }
}
```

