### FUNCION: deleteColumn
```js
function deleteColumn() {
    const letter = window.selectedColumnLetter;
    if (!letter) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    if (!confirm(`¿Estás seguro de que quieres eliminar permanentemente la Columna ${letter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Eliminar las celdas del grid (A-J).
    const cellsToDelete = document.querySelectorAll(`.cell.editable[data-col="${letter}"]`);
    cellsToDelete.forEach(cell => cell.remove());

    // 2. Eliminar la etiqueta de columna (A, B, C...).
    const colLetterElement = document.querySelector(`.col-letter[data-letter="${letter}"]`);
    if (colLetterElement) {
        colLetterElement.remove();
    }

    // 3. Reajustar el CSS Grid Layout y la estructura de columnas restantes.
    // Esta es la parte más compleja, requiere recalcular todas las propiedades grid.

    const spreadsheetContainer = document.getElementById('spreadsheet');
    if (!spreadsheetContainer) return;

    // Contar cuántas columnas quedan (originalmente 10).
    let remainingColumnsCount = document.querySelectorAll('.col-letter').length;

    // Resetear el grid-template-columns para reflejar la pérdida de una columna y mantener los demás espaciados uniformemente.
    if (remainingColumnsCount > 0) {
        spreadsheetContainer.style.gridTemplateColumns = `50px repeat(${remainingColumnsCount}, 1fr)`;
    } else {
        // Si se eliminan todas las columnas, solo queda la columna de etiquetas de fila.
        spreadsheetContainer.style.gridTemplateColumns = `50px`;
    }

    // Resetear el header principal para que no muestre los spans antiguos.
    const colLabelsHeader = document.querySelector('.col-labels');
    if (colLabelsHeader) {
         // Esto es un hack estructural, pero fuerza al contenedor de etiquetas a reajustarse
        colLabelsHeader.style.gridColumn = '2 / span 1'; // Simulación: solo ocupa una columna si el contenido se ha recalculado.
        // En un entorno real con JS puro sin frameworks, esto podría requerir reconstrucción parcial del DOM o manejo avanzado de CSS Grid Layouts.
    }

    alert(`Columna ${letter} eliminada exitosamente.`);
    window.selectedColumnLetter = null;
}
